using System;

namespace MaturityApp
{
    public sealed class ConnectionReference
    {
        public string Text, Url;
    }
    public static class ConnectionCatalog
    {
        public const string CheckedDate = "16.10.2026";
        // Reference information only: these entries never write actual installed products or maturity grades.
        public static ConnectionReference Find(string externalSystem)
        {
            string name = (externalSystem ?? "").ToUpperInvariant();
            if (name.Contains("ФРДО")) return Entry("У ФРДО есть разные способы доступа: ЗСПД 3608 и предусмотренный оператором вариант через ЕСИА для отдельных типов образовательных организаций. Уточните тип организации и выбранный способ. Конкретные СЗИ и их наличие не определяются названием системы.", "https://zspd.citis.ru/esia/");
            if (name.Contains("ГНА")) return Entry("ЦИТиС сообщает о выводе ЗСПД 3189 из эксплуатации в 2026 году. Текущий доступ к ФИС ГНА описан через TLS ГОСТ, браузер с поддержкой ГОСТ, КриптоПро CSP 5.0 R3 и ЕСИА организации. Старый профиль ViPNet 3189 нельзя считать текущим. Полный состав защиты локального АРМ требуется уточнить отдельно.", "https://zspd.citis.ru/3189/");
            if (name.Contains("ГИА")) return Entry("Различайте Сервис приёма и ППЭ / ЗСПД ГИА. Для ППЭ официальная страница ФЦТ указывает сеть 21387; у Сервиса приёма — отдельные варианты доступа через 13833 и разрешённое взаимодействие с 3608. Для рабочего профиля нужен соответствующий регламент. Частный регламент ФЦТ при проверке был недоступен.", "https://fis.rustest.ru/");
            if (name.Contains("СУПЕРСЕРВИС") || name.Contains("ПОСТУПЛЕНИЕ")) return Entry("Для «Поступления в вуз онлайн» проверьте вариант Сервиса приёма у оператора ЗСПД 13833, включая использование уже имеющегося подключения. Состав АРМ, роль организации и способ взаимодействия уточняются по текущим инструкциям. Инструкция апробации 2020 года не используется как постоянная основа.", "https://zspd.citis.ru/13833/");
            if (name.Contains("СЭП")) return Entry("АО «Электронный паспорт» публикует разные инструкции для разных ролей участника АС СЭП. Сначала выберите роль и её актуальную инструкцию; единая комплектация для всех участников не подтверждена. Часть подробных материалов доступна в профиле организации.", "https://elpts.ru/sep-connect/");
            if (name.Contains("ЕПТ")) return Entry("Найден официальный вариант: ИС ЕПТ Ростехнадзора. Если подключение относится к нему, используйте его регламент ЗСПД; документ предусматривает варианты криптозащиты. Ведомство и редакцию документа нужно подтвердить; сокращение «ЕПТ» само по себе их не определяет.", "https://www.gosnadzor.ru/eptb/");
            if (name.Contains("АИСТ")) return Entry("Ваш пример: ViPNet, SNS 8 либо Dallas Lock 8.0, отдельный или встроенный антивирус и выбранное СДЗ. Этот набор можно сохранить как рабочую основу. Публичное описание ЦИТиС историческое: организация сообщает, что уже не сопровождает АИСТ ГБД. Актуальную сеть и регламент подтверждает текущий оператор.", "https://citis.ru/citis_project_77.html");
            if (name.Contains("ЕГИСЗ")) return Entry("Подключение зависит от подсистемы и регионального оператора. Для примера региональный МИАЦ Новгородской области публикует собственную процедуру подключения через ЗСПД. Её сетевые параметры нельзя переносить на всю Россию. Выберите регион, подсистему и актуальный регламент своего оператора.", "https://miac53.ru/page/zspd");
            if (name.Contains("РМИАС") || name.Contains("ТФОМС")) return Entry("Требуется региональный профиль: субъект РФ, точное название подсистемы, оператор и действующий регламент подключения. Единый общероссийский набор продуктов и сетевых параметров в эту основу не подставляется.", "");
            return Entry("Уточните оператора, задачу подключения и действующий регламент. Технический состав можно сохранить своей основой; выбор названия внешней ИС не подтверждает наличие СЗИ, готовность объекта или оценки зрелости.", "");
        }
        static ConnectionReference Entry(string text, string url) { return new ConnectionReference { Text = text, Url = url }; }
    }
}
